/* global test expect */
import { DateTime } from "../src/luxon";

function refIsLeap(y) { return (y % 4 === 0 && y % 100 !== 0) || y % 400 === 0; }
function refDaysInMonth(y, m) {
  return [31, refIsLeap(y) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][m - 1];
}
function refAddMonths(y, m, d, n) {
  const total = (y * 12 + (m - 1)) + n;
  const ny = Math.floor(total / 12), nm = (total % 12) + 1;
  return { year: ny, month: nm, day: Math.min(d, refDaysInMonth(ny, nm)) };
}

test("brute force months", () => {
  const bad = [];
  for (let y = 95; y <= 105; y++) {
    for (let m = 1; m <= 12; m++) {
      for (let d = 26; d <= 31; d++) {
        if (d > refDaysInMonth(y, m)) continue;
        for (let n = -30; n <= 30; n++) {
          const dt = DateTime.fromObject({ year: y, month: m, day: d });
          if (!dt.isValid) { bad.push(`invalid start ${y}-${m}-${d}`); continue; }
          const res = dt.plus({ months: n });
          const exp = refAddMonths(y, m, d, n);
          if (res.year !== exp.year || res.month !== exp.month || res.day !== exp.day) {
            bad.push(`${y}-${m}-${d} +${n}m => ${res.year}-${res.month}-${res.day} expected ${exp.year}-${exp.month}-${exp.day}`);
          }
        }
      }
    }
  }
  console.log("bad count", bad.length);
  console.log(bad.slice(0, 40).join("\n"));
  expect(bad.length).toBe(0);
});
EOF
