    expect(() => Interval.fromISO(null, {})).toThrow("Invalid Interval");
  });

  // and the non-throwing behaviour is unchanged
  withThrowOnInvalid(false, () => {
    const i = Interval.fromISO("invalid", {});
    expect(i.isValid).toBe(false);
