/* global test expect */
import { DateTime } from "../src/luxon";

// Howard Hinnant civil calendar algorithms (proleptic Gregorian, exact)
function daysFromCivil(y, m, d) {
  y -= m <= 2 ? 1 : 0;
  const era = Math.floor(y / 400);
  const yoe = y - era * 400;
  const doy = Math.floor((153 * (m + (m > 2 ? -3 : 9)) + 2) / 5) + d - 1;
  const doe = yoe * 365 + Math.floor(yoe / 4) - Math.floor(yoe / 100) + doy;
  return era * 146097 + doe - 719468;
}
function civilFromDays(z) {
  z += 719468;
  const era = Math.floor(z / 146097);
  const doe = z - era * 146097;
  const yoe = Math.floor((doe - Math.floor(doe / 1460) + Math.floor(doe / 36524) - Math.floor(doe / 146096)) / 365);
  const y = yoe + era * 400;
  const doy = doe - (365 * yoe + Math.floor(yoe / 4) - Math.floor(yoe / 100));
  const mp = Math.floor((5 * doy + 2) / 153);
  const d = doy - Math.floor((153 * mp + 2) / 5) + 1;
  const m = mp + (mp < 10 ? 3 : -9);
  return { year: y + (m <= 2 ? 1 : 0), month: m, day: d };
}

test("brute force days", () => {
  const bad = [];
  for (let y = 95; y <= 105; y++) {
    for (let m = 1; m <= 12; m++) {
      for (let d = 1; d <= 31; d++) {
        const start = DateTime.fromObject({ year: y, month: m, day: d });
        if (!start.isValid) continue;
        for (let n = -800; n <= 800; n += 7) {
          const res = start.plus({ days: n });
          const exp = civilFromDays(daysFromCivil(y, m, d) + n);
          if (res.year !== exp.year || res.month !== exp.month || res.day !== exp.day) {
            bad.push(`${y}-${m}-${d} +${n}d => ${res.year}-${res.month}-${res.day} expected ${exp.year}-${exp.month}-${exp.day}`);
          }
        }
      }
    }
  }
  console.log("bad days", bad.length);
  console.log(bad.slice(0, 20).join("\n"));
  expect(bad.length).toBe(0);
});
EOF
